input:
#include <cmath>

void normalize(std::vector<float>& vec) {
    float len = 0;
    for (float x : vec) len += x*x;
    len = std::sqrt(len);
    for (float& x : vec) x /= len;
}

output:
#include <cmath>
#include <numeric>

void normalize(std::vector<float>& vec) {
    // Potential for std::transform or SIMD auto-vectorization
    float len_sq = std::accumulate(vec.begin(), vec.end(), 0.0f, 
        [](float sum, float x){ return sum + x*x; });
    float len = std::sqrt(len_sq);
    float inv_len = 1.0f / len; // Division is slow, multiplication is fast
    for (float& x : vec) x *= inv_len;
}
---
Optimized the division loop. Floating point division is significantly slower (20-40 cycles) than multiplication (3-5 cycles). Pre-calculating the reciprocal (1.0/len) and multiplying allows the CPU to process the array much faster.

