input:
#include <unordered_map>

struct Key {
    int x, y;
    // Default Hash is bad or missing
};

std::unordered_map<Key, int> cache;

output:
struct Key {
    int x, y;
    bool operator==(const Key& other) const { return x==other.x && y==other.y; }
};

struct KeyHash {
    std::size_t operator()(const Key& k) const {
        return std::hash<int>{}(k.x) ^ (std::hash<int>{}(k.y) << 1);
    }
};

std::unordered_map<Key, int, KeyHash> cache;
---
Provided a custom hash function. Without a good hash, or with a default one that generates collisions (e.g., just hashing the first field), std::unordered_map degrades from O(1) to O(N) as all elements land in the same bucket.

