// Trap rain water
int trap(const std::vector<int>& height) {
    int res = 0;
    for(int i=1; i<height.size()-1; ++i) {
        int max_l = 0, max_r = 0;
        for(int j=i; j>=0; --j) max_l = std::max(max_l, height[j]);
        for(int j=i; j<height.size(); ++j) max_r = std::max(max_r, height[j]);
