int trap(const std::vector<int>& height) {
    int l = 0, r = height.size() - 1, res = 0;
    int max_l = 0, max_r = 0;
    while (l < r) {
        if (height[l] < height[r]) {
            (height[l] >= max_l) ? max_l = height[l] : res += max_l - height[l];
            l++;
        } else {
            (height[r] >= max_r) ? max_r = height[r] : res += max_r - height[r];
            r--;
        }
    }
    return res;
}
