void multiply(const Matrix& A, const Matrix& B, Matrix& C) {
    int n = A.size;
    for(int i=0; i<n; ++i)
        for(int k=0; k<n; ++k) // Swapped loop order k-j
            for(int j=0; j<n; ++j)
                C.data[i*n + j] += A.data[i*n + k] * B.data[k*n + j];
