    std::vector<int> primes;
    if (max < 2) return primes;
    primes.reserve(max / std::log(max)); // Prime Number Theorem estimate
    primes.push_back(2);
    for(int i=3; i<=max; i+=2) {
        bool isPrime = true;
        for(int j=2; j*j<=i; ++j) {
