int max_gap_sorted(const std::vector<int>& nums) {
	if (nums.size() < 2) return 0;
	int n = nums.size();
	auto [min_it, max_it] = std::minmax_element(nums.begin(), nums.end());
	int min_val = *min_it, max_val = *max_it;
	if (min_val == max_val) return 0;
	int bucket_size = std::max(1, (max_val - min_val) / (n - 1));
	std::vector<int> b_min(n, 2147483647), b_max(n, -2147483648);
	for (int x : nums) {
		int idx = (x - min_val) / bucket_size;
		if (idx >= n) idx = n - 1;
		b_min[idx] = std::min(b_min[idx], x);
		b_max[idx] = std::max(b_max[idx], x);
	}
	int max_gap = 0, prev_max = min_val;
	for (int i = 0; i < n; ++i) {
		if (b_min[i] == 2147483647) continue;
		max_gap = std::max(max_gap, b_min[i] - prev_max);
		prev_max = b_max[i];
	}
	return max_gap;
