#include <iostream>
#include <vector>
#include <queue>

int dijkstra(int start, int end, int n, const std::vector<std::vector<std::pair<int, int>>>& adj) {
	std::vector<int> dist(n, 1e7);
	std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;
	dist[start] = 0;
	pq.push({0, start});
	while (!pq.empty()) {
		int d = pq.top().first, u = pq.top().second;
		pq.pop();
		if (d > dist[u]) continue;
		if (u == end) return d;
		for (auto& edge : adj[u]) {
			if (dist[u] + edge.second < dist[edge.first]) {
				dist[edge.first] = dist[u] + edge.second;
				pq.push({dist[edge.first], edge.first});
			}
		}
	}
	return dist[end];
}

int main() {
	int n = 3;
	std::vector<std::vector<std::pair<int, int>>> adj(n);
	adj[0].push_back({1, 5}); adj[1].push_back({2, 10}); adj[0].push_back({2, 20});
	std::cout << dijkstra(0, 2, n, adj) << std::endl;
	return 0;
}
---
