bool is_dag_kahn(int n, const std::vector<std::vector<int>>& adj) {
	std::vector<int> in_degree(n, 0);
	for (int u = 0; u < n; u++) {
		for (int v : adj[u]) in_degree[v]++;
	}
	std::queue<int> q;
	for (int i = 0; i < n; i++) if (in_degree[i] == 0) q.push(i);
	int count = 0;
	while (!q.empty()) {
		int u = q.front(); q.pop();
		count++;
		for (int v : adj[u]) {
			if (--in_degree[v] == 0) q.push(v);
		}
	}
	return count == n;
}

