int dijkstra(int n, const std::vector<std::vector<std::pair<int, int>>>& adj, int s, int t) {
	std::vector<int> dist(n, 1e7);
	std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;
	dist[s] = 0; pq.push({0, s});
	while (!pq.empty()) {
		int d = pq.top().first, u = pq.top().second; pq.pop();
		if (d > dist[u]) continue;
		for (auto& edge : adj[u]) {
			if (dist[u] + edge.second < dist[edge.first]) {
				dist[edge.first] = dist[u] + edge.second;
				pq.push({dist[edge.first], edge.first});
			}
		}
	}
	return dist[t];
}

int main() {
	int n = 3;
	std::vector<std::vector<std::pair<int, int>>> adj(n);
	adj[0].push_back({1, 5}); adj[1].push_back({2, 10});
	std::cout << dijkstra(n, adj, 0, 2) << std::endl;
	return 0;
}
---
The original Bellman-Ford style approach on an adjacency matrix runs in . Dijkstra's algorithm with a priority queue and adjacency list optimizes weighted shortest path calculation to , which is superior for graphs with non-negative weights.

