struct Edge { int u, v, w; };

struct DSU {
	std::vector<int> p;
	DSU(int n) : p(n) { std::iota(p.begin(), p.end(), 0); }
	int find(int i) { return p[i] == i ? i : p[i] = find(p[i]); }
	void unite(int i, int j) { p[find(i)] = find(j); }
};

int kruskal(int n, std::vector<Edge>& edges) {
	std::sort(edges.begin(), edges.end(), [](Edge a, Edge b) { return a.w < b.w; });
	DSU dsu(n);
	int mst_w = 0, count = 0;
	for (auto& e : edges) {
		if (dsu.find(e.u) != dsu.find(e.v)) {
			dsu.unite(e.u, e.v);
			mst_w += e.w;
			if (++count == n - 1) break;
		}
	}
	return mst_w;
}
---
Kruskal's algorithm with DSU and efficient sorting reduces MST finding from exponential to , which is optimal for edge-list based graph representations.

