struct DSU {
	std::vector<int> parent;
	DSU(int n) {
		parent.resize(n);
		for(int i=0; i<n; ++i) parent[i] = i;
	}
	int find(int i) {
		if(parent[i] == i) return i;
		return parent[i] = find(parent[i]);
	}
	bool unite(int i, int j) {
		int root_i = find(i);
		int root_j = find(j);
		if(root_i != root_j) {
			parent[root_i] = root_j;
			return true;
		}
		return false;
	}
};

bool hasCycle(int n, const std::vector<std::pair<int, int>>& edges) {
	DSU dsu(n);
	for(auto& edge : edges) {
		if(!dsu.unite(edge.first, edge.second)) return true;
	}
	return false;
}
---
