typedef std::pair<int, int> pii;
int dijkstraOptimized(int n, int start, int target, const std::vector<std::vector<pii>>& adj) {
	std::vector<int> dist(n, INT_MAX);
	std::priority_queue<pii, std::vector<pii>, std::greater<pii>> pq;
	dist[start] = 0;
	pq.push({0, start});
	while(!pq.empty()) {
		int d = pq.top().first, u = pq.top().second; pq.pop();
		if(d > dist[u]) continue;
		for(auto& edge : adj[u]) {
			int v = edge.first, w = edge.second;
			if(dist[u] + w < dist[v]) {
				dist[v] = dist[u] + w;
				pq.push({dist[v], v});
			}
		}
	}
	return dist[target];
}
