	std::vector<int> inDegree(n, 0), result;
	for(int u=0; u<n; ++u) for(int v : adj[u]) inDegree[v]++;
	std::queue<int> q;
	for(int i=0; i<n; ++i) if(inDegree[i] == 0) q.push(i);
