bool hasCycle(int u, const std::vector<std::vector<int>>& adj, std::vector<int>& state) {
	state[u] = 1; // Visiting
	for(int v : adj[u]) {
		if(state[v] == 1) return true;
		if(state[v] == 0 && hasCycle(v, adj, state)) return true;
	}
	state[u] = 2; // Visited
	return false;
}
---
The original code checks the entire path for every node, leading to O(V^2) or worse. Using 3-color DFS (unvisited, visiting, visited) allows cycle detection in a single O(V + E) pass by identifying back-edges.

