void bridgeDFS(int u, int p, int& timer, const std::vector<std::vector<int>>& adj, 
			   std::vector<int>& tin, std::vector<int>& low) {
	tin[u] = low[u] = timer++;
	for(int v : adj[u]) {
		if(v == p) continue;
		if(tin[v] != -1) low[u] = std::min(low[u], tin[v]);
		else {
