std::vector<int> findPathBFS(int start, int end, int n, const std::vector<std::vector<int>>& adj) {
	std::vector<int> parent(n, -1);
	std::queue<int> q;
	q.push(start); parent[start] = start;
	while(!q.empty()) {
		int u = q.front(); q.pop();
		if(u == end) {
			std::vector<int> path;
			for(int curr = end; curr != start; curr = parent[curr]) path.push_back(curr);
			path.push_back(start); std::reverse(path.begin(), path.end());
			return path;
		}
		for(int v : adj[u]) if(parent[v] == -1) { parent[v] = u; q.push(v); }
	}
	return {};
}
---
Recursive pathfinding without visited tracking is O(Branch^Depth). BFS with a parent array ensures O(V + E) complexity and guarantees finding the shortest path in terms of number of edges.

