int bfs(int s, int t, const std::vector<std::vector<int>>& adj, std::vector<std::vector<int>>& cap, std::vector<int>& parent) {
	std::fill(parent.begin(), parent.end(), -1);
	parent[s] = -2;
	std::queue<std::pair<int, int>> q;
	q.push({s, 1e9});
	while(!q.empty()) {
		int u = q.front().first, flow = q.front().second; q.pop();
		for(int v : adj[u]) {
			if(parent[v] == -1 && cap[u][v] > 0) {
				parent[v] = u;
				int new_flow = std::min(flow, cap[u][v]);
				if(v == t) return new_flow;
				q.push({v, new_flow});
			}
		}
	}
	return 0;
}
---
Edmonds-Karp implements the Ford-Fulkerson method using BFS to find augmenting paths, ensuring O(V * E^2) complexity. This is significantly faster than naive depth-based searches which can have exponential behavior depending on capacities.

