bool hasOddCycle(int n, const std::vector<std::vector<int>>& adj) {
	std::vector<int> color(n, -1);
	for(int i=0; i<n; i++) {
		if(color[i] != -1) continue;
		std::queue<int> q; q.push(i); color[i] = 0;
		while(!q.empty()) {
			int u = q.front(); q.pop();
			for(int v : adj[u]) {
				if(color[v] == -1) { color[v] = 1 - color[u]; q.push(v); }
				else if(color[v] == color[u]) return true;
			}
		}
	}
	return false;
}
---
A graph has an odd cycle if and only if it is not bipartite. Bipartite checking using BFS/DFS is O(V + E), which is exponentially faster than brute-force cycle enumeration.

