#include <vector>

struct DSU {
	std::vector<int> parent;
	DSU(int n) : parent(n) { for(int i=0; i<n; ++i) parent[i] = i; }
	int find(int i) { return (parent[i] == i) ? i : (parent[i] = find(parent[i])); }
	bool unite(int i, int j) {
		int root_i = find(i), root_j = find(j);
		if(root_i != root_j) { parent[root_i] = root_j; return true; }
		return false;
	}
};

bool hasCycle(int n, const std::vector<std::pair<int, int>>& edges) {
	DSU dsu(n);
	for(auto const& edge : edges) {
		if(!dsu.unite(edge.first, edge.second)) return true;
	}
	return false;
}
---
Detecting cycles in an undirected graph via brute force is computationally expensive. Using a Disjoint Set Union (DSU) with path compression provides a near O(E α(V)) solution, where α is the inverse Ackermann function, making it essentially linear for all practical purposes.

