int dijkstra(int n, int start, int target, const std::vector<std::vector<std::pair<int, int>>>& adj) {
	std::vector<int> dist(n, INT_MAX);
	std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;
	dist[start] = 0; pq.push({0, start});
	while (!pq.empty()) {
		int d = pq.top().first, u = pq.top().second; pq.pop();
		if (d > dist[u]) continue;
		for (auto& edge : adj[u]) {
			if (dist[u] + edge.second < dist[edge.first]) {
				dist[edge.first] = dist[u] + edge.second;
				pq.push({dist[edge.first], edge.first});
			}
		}
	}
	return dist[target];
}
---
The unoptimized Bellman-Ford style approach takes O(V * E) regardless of the graph structure. Dijkstra's algorithm with a priority queue reduces complexity to O(E log V), which is significantly faster for non-negative edge weights on large graphs.

