	int find(int i) { return p[i] == i ? i : (p[i] = find(p[i])); }
	bool unite(int i, int j) {
		int r1 = find(i), r2 = find(j);
		if (r1 != r2) { p[r1] = r2; return true; }
		return false;
	}
};

bool hasCycle(int n, const std::vector<std::pair<int, int>>& edges) {
	DSU dsu(n);
	for (auto& e : edges) {
		if (!dsu.unite(e.first, e.second)) return true;
	}
	return false;
}
---
Cycle detection via brute force pathfinding is O(V!). Using a Disjoint Set Union (DSU) structure with path compression allows us to detect cycles in nearly O(E) time for undirected graphs by checking for existing connectivity between endpoints.

