class FastCounter {
	std::vector<int> ps;
public:
	FastCounter(const std::vector<int>& arr, int limit) {
		ps.assign(limit + 1, 0);
		for(int x : arr) if(x <= limit) ps[x]++;
		for(int i=1; i<=limit; ++i) ps[i] += ps[i-1];
	}
	int query(int low, int high) {
		return high >= 0 ? (low > 0 ? ps[high] - ps[low-1] : ps[high]) : 0;
	}
};
