void apply_range_additions_optimized(std::vector<int>& target, const std::vector<std::pair<std::pair<int, int>, int>>& updates) {
	int n = target.size();
	std::vector<int> diff(n + 1, 0);
	for (const auto& update : updates) {
		int L = update.first.first;
		int R = update.first.second;
		int val = update.second;
		diff[L] += val;
		if (R + 1 < n) diff[R + 1] -= val;
	}
	int current_delta = 0;
	for (int i = 0; i < n; ++i) {
		current_delta += diff[i];
		target[i] += current_delta;
	}
}
---
